function [fitPct, kEff] = validate_step(t, u, x)
% VALIDATE_STEP  Compare plant_model against a recorded open-loop pulse response.
%   [fitPct, kEff] = validate_step(t, u, x)
%     t - time [s], u - applied voltage [V], x - payload position [m]
%     fitPct - NRMSE fit [%] (100 = perfect, 0 = no better than a flat line)
%     kEff   - measured / modelled payload travel. Absorbs eta < 1, friction
%              and gravity, none of which are in the linear model.
%   validate_step()  runs a self-check on data generated by the model itself.
%
% Recording: actuator at the bottom, payload at rest, log ~2 s of rest, then a
% short pulse (e.g. +1 V for 0.3 s, ~13 mm travel), then log until it has rung
% for ~10 s. A held step drives the actuator into its end stop within ~1 s.
%
% From an SLRT run in the Simulation Data Inspector:
%   ids = Simulink.sdi.getAllRunIDs;  r = Simulink.sdi.getRun(ids(end));
%   sigs = r.getAllSignals;  disp({sigs.Name}')   % pick the voltage and X [m]
%   validate_step(sigs(1).Values.Time, sigs(2).Values.Data, sigs(1).Values.Data)

if nargin == 0, selfCheck(); return; end
t = t(:) - t(1); u = double(u(:)); x = double(x(:));

sys = loadModel();
% Deviation model: start from rest at the pre-pulse position
iRest = t < max(t(find(abs(u) > 0.05, 1)) - 0.1, t(2));
xRest = mean(x(iRest));
dx = x - xRest;

[~, ~, xs] = lsim(sys, min(max(u, -5), 5), t);   % same ±5 V limit as the interface
dxModel = xs(:, 4);
yModel  = xs(:, 2);

% Travel after the pulse, averaged over the last 20% so the ringing cancels out
iEnd = t > 0.8*t(end);
kEff = mean(dx(iEnd)) / mean(dxModel(iEnd));
fitPct = 100*(1 - norm(dx - dxModel)/norm(dx - mean(dx)));
fitScaled = 100*(1 - norm(dx - kEff*dxModel)/norm(dx - mean(dx)));

fprintf('travel: measured %.2f mm, model %.2f mm -> kEff = %.3f\n', 1e3*mean(dx(iEnd)), 1e3*mean(dxModel(iEnd)), kEff);
fprintf('fit: %.1f %% as modelled, %.1f %% with input gain scaled by kEff\n', fitPct, fitScaled);
fprintf('model actuator peak y = %.1f mm above start\n', 1e3*max(yModel));

if nargout == 0
  figure;
  subplot(2,1,1);
  plot(t, u, 'r'); ylabel('Voltage [V]'); grid on; title('Input v(t)');
  subplot(2,1,2);
  plot(t, 1e3*dx, 'b', t, 1e3*dxModel, 'k--');
  ylabel('Position [mm]'); xlabel('Time [s]'); grid on; title('Payload position x(t)');
  legend('Measured', 'Model (Table 1 gain, \tau_m 18 ms)', 'Location', 'northoutside', 'Orientation', 'horizontal');
end
end

function selfCheck()
[sys, x0] = loadModel();
t = (0:1e-4:12)';
u = 1.0*(t >= 2 & t < 2.3);
[xm, ~] = lsim(sys, u, t);
x = x0 + 0.8*xm + 10e-6*randn(size(t));   % 20% weaker drive, as eta < 1 would give
[fitPct, kEff] = validate_step(t, u, x);
assert(abs(kEff - 0.8) < 0.02, 'kEff off: %.3f vs 0.8', kEff);
assert(fitPct < 90, 'unscaled fit should show the gain error: %.1f', fitPct);
disp('validate_step self-check passed');
end

function [sys, x0] = loadModel()
% Final model: Table 1 input gain (kv 0.99, closed-loop frequency response), tauM 18 ms.
% On last_run.mat kEff = 0.66: friction and eta < 1 eat a third of a short open-loop pulse.
[sys, p] = plant_model(1, 0.99, 0.018);
x0 = p.x0;
end
